-- v992: контент курса «Адаптация» — День 4 · Продукт: глубина и ROI. Сгенерировано gen-academy-adaptation.mjs

INSERT INTO academy_modules (id, course_id, sort, title, intro, gate, active) VALUES
 ($sd$a0000000-0000-0000-0002-000000000004$sd$, $sd$c0000000-0000-0000-0000-000000000002$sd$, 50, $sd$День 4 · Продукт: глубина и ROI$sd$, $sd$Цена, лицензии, внедрение — и главный инструмент продажи: расчёт выгоды клиента. Плюс банк возражений и отстройка от конкурентов.$sd$, $sd${"title":"Зачёт дня 4","tasks":["5-минутная структурированная презентация для условного клиента B-сегмента: боль → решение → ценность","Ролёвка по трём возражениям: «Дорого, у нас самописная система», «Слишком сложно внедрять, нет времени», «Покажите реальные цифры для компании нашего размера»","Калькулятор выгоды: 15 агентов + 5 логистов — заполненный калькулятор, названы месячная выгода и срок окупаемости","Называешь три УТП и модель цены без подсказок"],"result":"Готов вести разговор о ценности и экономической выгоде, а не только о функционале."}$sd$::jsonb, true)
ON CONFLICT (id) DO UPDATE SET course_id = EXCLUDED.course_id, sort = EXCLUDED.sort, title = EXCLUDED.title, intro = EXCLUDED.intro, gate = EXCLUDED.gate, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000401$sd$, $sd$a0000000-0000-0000-0002-000000000004$sd$, 10, $sd$Лицензирование, цена, внедрение$sd$, $sd$15 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Стоимость лицензии:","options":["$100 за компанию в месяц","$10 за пользователя в месяц","$1 000 в год","$10 за торговую точку"],"correct":1},{"q":"Что входит в базовую лицензию?","options":["Только веб-версия","Неограниченные клиенты, приложение iOS/Android, поддержка 24/7, обновления","Интеграция с 1С","Внедрение под ключ"],"correct":1},{"q":"С какой версией 1С НЕ интегрируемся?","options":["8.3","УТ 11","7.7","ERP"],"correct":2},{"q":"Сколько занимает стандартное внедрение?","options":["1 день","2–3 недели","3–6 месяцев","1 год"],"correct":1},{"q":"Четыре этапа внедрения по порядку:","options":["Пилот → настройка → диагностика → внедрение","Диагностика → настройка → пилот → полное внедрение","Договор → оплата → обучение → поддержка","Настройка → диагностика → внедрение → пилот"],"correct":1}]$sd$::jsonb, $sd$<h4>Модель</h4>
<ul>
<li><b>SaaS-подписка: $10 за пользователя в месяц.</b> В скрипте: «стоимость от $10 за пользователя, внедрение от $1 000 — в зависимости от количества пользователей и интеграций».</li>
<li><b>Базовая лицензия включает:</b> неограниченное количество клиентов (торговых точек), мобильное приложение iOS / Android, техподдержку 24/7, регулярные обновления.</li>
<li><b>Дополнительные услуги:</b> внедрение и настройка — от $1 000 (пакеты стандарт / стандарт плюс / премиум); интеграция с 1С / ERP; разработка кастомных модулей — цены индивидуально.</li>
<li><b>Интеграция с 1С:</b> все версии, кроме 1С 7.7. На квалификации уточняем конфигурацию (УТ, КА, ERP) и платформу.</li>
</ul>
<h4>Четыре этапа внедрения — стандартно 2–3 недели</h4>
<div class="flow"><span class="node">Диагностика · 3–5 дней</span><span class="arr">→</span><span class="node">Настройка · 1–2 нед</span><span class="arr">→</span><span class="node">Пилот · 2 нед</span><span class="arr">→</span><span class="node">Полное внедрение · 1–2 нед</span></div>
<p>Оффер «запуск за 7 дней» действует, если интеграция не требуется. Пилот на 5–7 пользователях в боевом режиме — способ снять риск для клиента.</p>
<h4>Пример расчёта для B-сегмента, 20 лицензий</h4>
<p>20 × $10 = $200 / мес. Экономия у клиента ~ $1 500 / мес → окупаемость около месяца. Именно так звучит ответ на «дорого».</p>
<div class="callout">Единого прайса как документа пока нет — цены на внедрение и интеграцию уточняй у наставника до отправки первого КП.</div>$sd$, $sd$[{"t":"Тест по продукту (уровни 1–3)","u":"https://docs.google.com/spreadsheets/d/1Fo-mBEdph1TaSmYjPj4Dts2Ilkj9LZaqH5TWJGt4Rwo/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000402$sd$, $sd$a0000000-0000-0000-0002-000000000004$sd$, 20, $sd$Модель ROI — как считать выгоду клиента$sd$, $sd$25 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Три модели ROI:","options":["Цена, скидка, бонус","Потери заявок, экономия времени торговых, логистика","Лицензии, внедрение, интеграция","Агенты, супервайзеры, директор"],"correct":1},{"q":"Когда на встрече считать ROI?","options":["В самом начале","После демо, когда клиент увидел решение","После подписания договора","В КП, без клиента"],"correct":1},{"q":"Формула ROI №1:","options":["Агенты × лицензия","Потерянные заявки в день × чек × маржа × рабочих дней","Доставки × км","Бюджет ГСМ × 15 %"],"correct":1},{"q":"Какой процент бюджета ГСМ обычно уходит на левые рейсы?","options":["1–2 %","10–20 %","50 %","0 %"],"correct":1},{"q":"Какие ячейки в калькуляторе заполняет менеджер?","options":["Зелёные","Синие","Чёрные","Все"],"correct":1}]$sd$::jsonb, $sd$<p>ROI — главный инструмент продаж. Не функционал, а деньги клиента. Три модели, каждая — своя формула и свои вопросы.</p>
<h4>ROI №1 — потери из-за пропущенных заявок</h4>
<p><code>потерянные заявки в день × средний чек × маржа × рабочих дней</code></p>
<ul><li>«Сколько заказов в день приходит от магазинов?»</li><li>«Сколько теряется / путается / не доезжает — хотя бы в процентах?»</li><li>«Средний чек заказа? Маржа примерно 10–20 %?»</li></ul>
<h4>ROI №2 — экономия времени торговых</h4>
<p><code>кол-во торгпредов × экономия минут в день × рабочих дней × стоимость часа</code> — или, как в калькуляторе: сэкономленное время → дополнительные визиты → дополнительные заказы × чек × маржа.</p>
<ul><li>«Сколько времени уходит на отчёты, переписки, сверки?»</li><li>«Если сэкономим 30–60 минут в день на человека — это важно?»</li></ul>
<h4>ROI №3 — логистика (детальный расчёт)</h4>
<ul>
<li><b>Маршруты:</b> «Сколько километров проезжает экспедитор на одну доставку? Бывает, что кружит в поисках магазина?» → экономия км × расход × цена литра.</li>
<li><b>Возвраты:</b> «Бывает, экспедитор говорит: магазин закрыт, клиент отказался?» → снижение возвратов с ~3 % до 2 %.</li>
<li><b>ГСМ и левые рейсы:</b> «Чувствуете, что ГСМ уходит больше, чем должно?» → GPS-контроль экономит 10–20 % бюджета ГСМ.</li>
<li><b>Штат:</b> «С оптимальными маршрутами можно меньше машин использовать?»</li>
</ul>
<p><b>Итог:</b> ROI = ROI₁ + ROI₂ + ROI₃ − стоимость системы. Калькулятор считает всё автоматически: заполняешь синие ячейки, оранжевый текст — вопросы клиенту, зелёные — итог: выгода в месяц и год, чистая выгода за первый год, ROI в процентах, окупаемость в месяцах.</p>
<h4>Как встроить ROI во встречу, чтобы не было «допроса»</h4>
<div class="flow"><span class="node">5 мин · квалификация</span><span class="arr">→</span><span class="node">15 мин · демо по боли</span><span class="arr">→</span><span class="node me">2 мин · «давайте на ваших цифрах прикинем окупаемость»</span></div>
<p>Не считать в начале. Считать после того, как клиент «увидел». Так ROI не выглядит давлением.</p>
<div class="callout"><b>Упражнение на зачёт:</b> 15 агентов + 5 логистов. Заполни калькулятор, назови месячную выгоду и срок окупаемости.</div>$sd$, $sd$[{"t":"Калькулятор ROI · таблица","u":"https://docs.google.com/spreadsheets/d/1z_lwR6M784K7OhJzk8Uf_SS8Bo4tkBjAe3OhtJAKbAs/edit"},{"t":"Модель ROI · описание","u":"https://docs.google.com/document/d/1ks6r_K3gYx6ROtylMP7QC1UJsAebQ7kZ_0_CsSRBVf4/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000403$sd$, $sd$a0000000-0000-0000-0002-000000000004$sd$, 30, $sd$Банк возражений$sd$, $sd$20 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"«Слишком дорого». Тактика «разделение стоимости» — это…","options":["Скидка 50 %","«Поделить на 10 агентов — $1 в день на каждого»","Рассрочка","Убрать модуль"],"correct":1},{"q":"Что такое «эффект холодильника»?","options":["Охладить клиента","Подсветить, что «всё работает», пока не вскрылись потери","Отложить сделку","Показать конкурента"],"correct":1},{"q":"«Я не принимаю решение». Что делаем?","options":["Заканчиваем разговор","Выявляем ЛПР через союзника, готовим выжимку на 1 страницу","Звоним директору напрямую","Просим контакт бухгалтера"],"correct":1},{"q":"Что такое предвосхищение возражения?","options":["Ответ после возражения","Снять возражение до того, как клиент его сказал","Игнорирование","Перенос встречи"],"correct":1},{"q":"«Давайте потом, не сейчас». Тактика «окно возможности»:","options":["Дать скидку","«Сейчас есть ресурсы на быстрый запуск — потом можем попасть в очередь»","Согласиться и ждать","Позвонить директору"],"correct":1}]$sd$::jsonb, $sd$<h4>Предвосхищение — до того, как клиент сказал</h4>
<ul>
<li>«Я понимаю, что у вас уже выстроен свой процесс — именно поэтому на встрече покажем, где теряются заявки и как автоматизация устраняет потери без стресса.»</li>
<li>«Многие вначале сравнивают нас по цене — именно поэтому сразу даём чек-лист, что включено и где система быстро окупается.»</li>
<li>«Понимаю, что решение требует обдумывания — именно поэтому на демо сразу разберём ключевые моменты, чтобы проще было сравнить.»</li>
</ul>
<h4>Шесть возражений и тактики</h4>
<table class="tbl"><thead><tr><th>Возражение</th><th>Тактика</th><th>Фраза</th></tr></thead><tbody>
<tr><td rowspan="2"><b>Нам и так нормально, всё вручную</b></td><td>«Эффект холодильника» — всё работает, пока не вскрылись потери</td><td>«Обычно так и бывает — до первого сбоя или потери заявок. Покажу, как у других, и вы сами решите.»</td></tr>
<tr><td>«Пробник будущего»</td><td>«У других дистрибьюторов было так же: заявки, логистика, доставка — в разных системах. После — единая система. Покажу?»</td></tr>
<tr><td rowspan="2"><b>Слишком дорого</b></td><td>Разделение стоимости</td><td>«Если поделить на 10 агентов — это $1 в день на каждого.»</td></tr>
<tr><td>Окупаемость</td><td>«Если хотя бы 1 заявка в день не теряется — система себя окупает. Прикину, как у вас?»</td></tr>
<tr><td rowspan="2"><b>Надо подумать</b></td><td>Присоединение + следующий шаг</td><td>«Конечно. Именно поэтому давайте зафиксируем бонус, а вы спокойно обдумаете.»</td></tr>
<tr><td>Помощь в размышлении</td><td>«Чтобы проще определиться — скину чек-лист для сравнения.»</td></tr>
<tr><td rowspan="2"><b>Давайте потом</b></td><td>Фиксация выгоды сейчас</td><td>«Сейчас есть свободные ресурсы под внедрение — зафиксируем слот, вернёмся к запуску позже.»</td></tr>
<tr><td>Окно возможности</td><td>«Сейчас есть ресурсы на быстрый запуск — потом можем попасть в очередь.»</td></tr>
<tr><td rowspan="2"><b>Я не принимаю решение</b></td><td>Выявление ЛПР через союзника</td><td>«Кто обычно участвует в решении? Дам материалы, чтобы обсудили вместе.»</td></tr>
<tr><td>Каскадный прогресс</td><td>«Подготовлю выжимку на 1 страницу, чтобы проще передать ключевое.»</td></tr>
<tr><td rowspan="2"><b>У нас уже есть система</b></td><td>Присоединение + смелое сравнение</td><td>«Сегодня почти у всех что-то стоит. Именно поэтому предлагаю сравнить лоб в лоб: где удобнее, быстрее, выгоднее.»</td></tr>
<tr><td>Фокус на последствия</td><td>«Вопрос — приносит ли она максимум результата? Хотите прикину, где вы теряете?»</td></tr>
</tbody></table>
<p>Как отрабатывать возражение прямо на демо-встрече (алгоритм LAER) — в стандарте демо, день 6.</p>$sd$, $sd$[{"t":"Банк возражений","u":"https://docs.google.com/spreadsheets/d/1FBFcPBdpuvGDZHi6kMI5h6InNmKjADuaT6Lnm-92GII/edit"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;

INSERT INTO academy_lessons (id, module_id, sort, title, duration_label, cards, trainer, questions, body_html, links, pass_score, ack_text, active) VALUES
 ($sd$b0000000-0000-0000-0002-000000000404$sd$, $sd$a0000000-0000-0000-0002-000000000004$sd$, 40, $sd$Отстройка от конкурентов$sd$, $sd$10 мин$sd$, '[]'::jsonb, NULL, $sd$[{"q":"Кто делает интеграцию у нас?","options":["Сторонний подрядчик","Своя команда интеграторов через собственный API","Клиент сам","1С-франчайзи"],"correct":1},{"q":"Что у нас есть, чего нет у большинства конкурентов?","options":["Веб-версия","Полноценное iOS-приложение для агентов","Android-приложение","Телефонная поддержка"],"correct":1},{"q":"Сколько занимает внедрение у конкурентов по нашей отстройке?","options":["1 неделя","2–3 недели","3–6 месяцев","1 год"],"correct":2},{"q":"Мы — …","options":["Реселлер","Прямой филиал разработчика","Маркетплейс","Интегратор 1С"],"correct":1}]$sd$::jsonb, $sd$<p>Шесть аргументов, каждый — экспертная формулировка и почему это важно клиенту.</p>
<ol class="rules">
<li><b>Собственный API и своя команда интеграторов.</b> «Конкуренты отдают интеграцию подрядчикам. Мы разработали свой API и сами запускаем и бесплатно сопровождаем интеграцию.» → Быстрый старт без посредников, нет доплат за исправления, бизнес не встанет при уходе подрядчика.</li>
<li><b>Полноценное iOS-приложение для агентов.</b> «У большинства — только Android или урезанный веб.» → Работает на любом устройстве, важно для руководителей и агентов с iPhone.</li>
<li><b>Фокус только на FMCG-дистрибуции.</b> «Мы не делаем универсальные CRM: учитываем полку, акции, остатки, KPI торговой команды.» → Решение под бизнес-модель, без переплаты за лишнее.</li>
<li><b>Вся цепочка: агент → супервайзер → доставщик → экспедитор.</b> «Другие автоматизируют только агентов.» → Ошибок минимум на 25 % меньше, полная прозрачность.</li>
<li><b>Прямой филиал разработчика, а не реселлер.</b> → Долгосрочная поддержка и развитие, нет риска «бросить клиента».</li>
<li><b>Рост продаж и контроль KPI.</b> «Автоматизируем не ради отчётов, а ради денег: +20–30 % эффективности продаж.» → Связь расходов с результатом в деньгах — главное для владельца.</li>
</ol>
<h4>Три УТП для теста</h4>
<p>Специализация только на дистрибуции · работа офлайн в полевых условиях · внедрение за 2–3 недели (у конкурентов 3–6 месяцев).</p>$sd$, $sd$[{"t":"Отстройка от конкурентов","u":"https://drive.google.com/file/d/186YC-G-kxLZf9-kKwlcipJm7N4QKp9PM/view"}]$sd$::jsonb, NULL, NULL, true)
ON CONFLICT (id) DO UPDATE SET module_id = EXCLUDED.module_id, sort = EXCLUDED.sort, title = EXCLUDED.title, duration_label = EXCLUDED.duration_label, questions = EXCLUDED.questions, body_html = EXCLUDED.body_html, links = EXCLUDED.links, pass_score = EXCLUDED.pass_score, ack_text = EXCLUDED.ack_text, active = EXCLUDED.active;
